using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace PlainApi.Evals.Tests;

[TestClass]
public sealed class ApiEvaluationTests
{
    private static WebApplicationFactory<Program> _factory = null!;

    [ClassInitialize]
    public static void ClassInit(TestContext context)
    {
        _factory = new WebApplicationFactory<Program>();
    }

    [ClassCleanup]
    public static void ClassCleanup()
    {
        _factory.Dispose();
    }

    [TestMethod]
    public async Task RootEndpoint_ReturnsExpectedResponse()
    {
        var client = _factory.CreateClient();
        var response = await client.GetAsync("/");

        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync();

        Assert.AreEqual("Hello, World!", content);
    }

    [TestMethod]
    public async Task RootEndpoint_QualityEvaluation()
    {
        // Quality evaluators require an LLM judge model.
        // Set EVAL_CHAT_MODEL_ENDPOINT and EVAL_CHAT_MODEL_KEY to enable.
        var endpoint = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_ENDPOINT");
        if (string.IsNullOrEmpty(endpoint))
        {
            Assert.Inconclusive(
                "Skipped: set EVAL_CHAT_MODEL_ENDPOINT to run quality evaluations.");
            return;
        }

        var client = _factory.CreateClient();
        var response = await client.GetAsync("/");
        var content = await response.Content.ReadAsStringAsync();

        var evaluator = new CompositeEvaluator(
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator());

        var chatConfig = CreateChatConfiguration(endpoint);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What does the root endpoint return?")
        };
        var modelResponse = new ChatResponse(new ChatMessage(ChatRole.Assistant, content));

        var metrics = await evaluator.EvaluateAsync(
            messages, modelResponse, chatConfig);

        Assert.IsNotNull(metrics);
        foreach (var metric in metrics)
        {
            Assert.IsFalse(
                metric.Diagnostics?.Any(d =>
                    d.Severity == EvaluationDiagnosticSeverity.Error) ?? false,
                $"Metric '{metric.Name}' reported errors.");
        }
    }

    private static ChatConfiguration CreateChatConfiguration(string endpoint)
    {
        var key = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_KEY") ?? string.Empty;
        var modelId = Environment.GetEnvironmentVariable("EVAL_CHAT_MODEL_ID") ?? "gpt-4o-mini";

        IChatClient chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(modelId)
            .AsIChatClient();

        return new ChatConfiguration(chatClient);
    }
}

